const data = $input.first().json;

// 1. Rekap per stage
const stageIcons = {
  'PO': '📝',
  'Staging': '⚙️',
  'QC': '🔍',
  'Ready to Delivery': '📦',
  'In Transit': '🚚',
  'Waiting Customer Schedule': '⏳',
  'Scheduled': '📅',
  'On Hold': '⏸️',
  'Deployed': '✅'
};

const stageLines = data.stages.map(s => {
  const icon = stageIcons[s.stage] || '•';
  return `${icon} <b>${s.stage}</b>: ${s.total} unit`;
}).join('\n');

// 2. Sample overdue internal (max 3)
const overdueCount = data.internal_overdue.length;
let overdueText = '<i>Tidak ada unit overdue.</i>';
if (overdueCount > 0) {
  const sample = data.internal_overdue.slice(0, 3).map(u => 
    `  • <code>${u.serial_number}</code> [${u.current_stage}] (${u.days_stuck} hari)`
  ).join('\n');
  overdueText = `<b>${overdueCount} unit tertahan:</b>\n${sample}`;
  if (overdueCount > 3) overdueText += `\n  <i>+ ${overdueCount - 3} unit lainnya</i>`;
}

// 3. Sample idle delivery (max 3)
const idleCount = data.idle_delivery.length;
let idleText = '<i>Semua pengiriman on-track.</i>';
if (idleCount > 0) {
  const sample = data.idle_delivery.slice(0, 3).map(u => 
    `  • <code>${u.serial_number}</code> [${u.courier_name}] (${u.days_idle} hari / max: ${u.max_ready_days}h)`
  ).join('\n');
  idleText = `<b>${idleCount} unit melebihi batas kurir:</b>\n${sample}`;
  if (idleCount > 3) idleText += `\n  <i>+ ${idleCount - 3} unit lainnya</i>`;
}

const pesan = `📋 <b>RINGKASAN OPERASIONAL PAGI</b>
📅 <i>${new Date().toLocaleDateString('id-ID', { dateStyle: 'full' })}</i>
Total Armada: <b>${data.total_units} unit</b>

<b>Distribusi Status:</b>
${stageLines}

━━━━━━━━━━━━━━━━━━━━
⚠️ <b>Overdue Internal (PO/Staging/QC > 1h):</b>
${overdueText}

📦 <b>Idle Ready to Delivery:</b>
${idleText}

<i>Sistem otomatis @itsm_escalator_bot</i>`;

return [{ json: { message_text: pesan } }];
